import numpy as np
from scipy.optimize import minimize

def f(x, y):
    return 3*x**2 + 3*y**2 - x**2*y**2 - 8*x*y - 1

def objective(a):
    vals = []
    n = len(a)
    for i in range(n):
        for j in range(i + 1, n):
            vals.append(f(a[i], a[j]))
    return -min(vals)

def solve_n3():
    best_min_f = -float('inf')
    best_a = None
    for _ in range(50):
        a0 = sorted(np.random.uniform(0, 3, 3))
        res = minimize(objective, a0, bounds=[(0, 3), (0, 3), (0, 3)], method='SLSQP')
        if res.success:
            min_f = -res.fun
            if min_f > best_min_f:
                best_min_f = min_f
                best_a = res.x
    return best_min_f, best_a

print(f"Best min_f for n=3: {solve_n3()[0]}")
print(f"Best a for n=3: {solve_n3()[1]}")

